// Distribute over union arms, then remove null/undefined BEFORE recursing. A
// nullable object must exercise its fields, not pass merely by choosing null.
type WireFixtureRequired<T> = T extends unknown ? [NonNullable<T>] extends [never] ? never : NonNullable<T> extends readonly (infer E)[]
  ? WireFixtureRequired<E>[] : NonNullable<T> extends object
  ? { [K in keyof NonNullable<T>]-?: WireFixtureRequired<NonNullable<T>[K]> } : NonNullable<T> : never;
