type KeysOfUnion<T> = T extends unknown ? keyof T : never;
type AssertNever<T extends never> = T;
type RuntimeChangeCoverage = AssertNever<Exclude<keyof IndexChangeWire, KeysOfUnion<typeof fixtures['indexChange.runtime.session.json'] | typeof fixtures['indexChange.runtime.project.json'] | typeof fixtures['indexChange.runtime.file.json'] | typeof fixtures['indexChange.runtime.deleted.json']>>>;
type ProtocolChangeCoverage = AssertNever<Exclude<keyof IndexChange, KeysOfUnion<typeof fixtures['indexChange.protocol.session.json'] | typeof fixtures['indexChange.protocol.project.json'] | typeof fixtures['indexChange.protocol.file.json'] | typeof fixtures['indexChange.protocol.deleted.json']>>>;

