const root = resolve(dirname(fileURLToPath(import.meta.url)), '../../../../..');
const fixtureDir = resolve(root, 'packages/collab-protocol/fixtures');
const directions = ['desktopToServer', 'iosToServer', 'serverToDesktop', 'serverToIos', 'desktopToIos'];
it('validates manifest metadata and binds every JSON file to its exhaustive witness', () => {
  const manifest = JSON.parse(readFileSync(resolve(fixtureDir, 'index.json'), 'utf8'));
  expect(Object.keys(manifest).sort()).toEqual(['contractRevision', 'findings', 'fixtures']);
  expect(manifest.contractRevision).toBe(2);
  expect(Array.isArray(manifest.findings)).toBe(true);
  for (const finding of manifest.findings) { expect(typeof finding).toBe('string'); expect(finding.trim().length).toBeGreaterThan(0); }
  expect(Array.isArray(manifest.fixtures)).toBe(true);
  const listed = new Set<string>();
  const routes = new Set<string>();
  for (const row of manifest.fixtures) {
    expect(Object.keys(row).filter(key => !['file', 'tsType', 'tsSource', 'direction', 'swiftType', 'swiftSource', 'notes', 'swiftPayloadPath'].includes(key))).toEqual([]);
    expect(typeof row.file).toBe('string');
    expect(Object.hasOwn(fixtures, row.file), row.file).toBe(true);
    expect(row.file.endsWith('.json')).toBe(true);
    for (const field of ['tsType', 'tsSource', 'swiftSource']) {
      expect(typeof row[field], field).toBe('string');
      expect(row[field].trim().length, field).toBeGreaterThan(0);
    }
    expect(statSync(resolve(root, row.tsSource)).isFile(), row.tsSource).toBe(true);
    expect(statSync(resolve(root, row.swiftSource)).isFile(), row.swiftSource).toBe(true);
    expect(directions).toContain(row.direction);
    if (row.swiftType === null) expect(row.notes?.trim().length ?? 0).toBeGreaterThan(0);
    else { expect(typeof row.swiftType).toBe('string'); expect(row.swiftType.trim().length).toBeGreaterThan(0); }
    if (row.notes !== undefined) { expect(typeof row.notes).toBe('string'); expect(row.notes.trim().length).toBeGreaterThan(0); }
    if (row.swiftPayloadPath !== undefined) { expect(typeof row.swiftPayloadPath).toBe('string'); expect(row.swiftPayloadPath.trim().length).toBeGreaterThan(0); }
    const route = row.file + ':' + row.direction;
    expect(routes.has(route), route).toBe(false); routes.add(route); listed.add(row.file);
  }
  expect([...listed].sort()).toEqual(Object.keys(fixtures).sort());
  expect(readdirSync(fixtureDir).filter(file => file.endsWith('.json') && file !== 'index.json').sort()).toEqual(Object.keys(fixtures).sort());
  for (const [file, witness] of Object.entries(fixtures)) {
    const value = JSON.parse(readFileSync(resolve(fixtureDir, file), 'utf8'));
    expect(value, file).toEqual(witness);
    // Exercise the production pre-decryption validator on both protocol and
    // runtime specimens, including every embedded page entry.
    const changes = value.type === 'indexPageResponse' ? value.entries : 'entity' in value ? [value] : [];
    for (const change of changes) expect(() => assertValidIndexChange(change), file).not.toThrow();
  }
  for (const coverage of [clientCoverage, serverCoverage] as Array<Record<string, Coverage>>) for (const [type, entry] of Object.entries(coverage)) {
    if ('fixture' in entry) expect(fixtures[entry.fixture]).toHaveProperty('type', type);
    else expect(entry.reason.trim().length).toBeGreaterThan(0);
  }
});
